"""``constants.py`` 的回归测试：保证集中常量的语义不变式。"""

from app.ui.graph.library_pages.entity_placement import constants as C


def test_item_roles_are_distinct_and_above_user_role():
    assert len(set(C.ITEM_ROLES)) == len(C.ITEM_ROLES)
    assert all(role >= 0x0100 for role in C.ITEM_ROLES)


def test_item_roles_are_contiguous():
    assert list(C.ITEM_ROLES) == list(range(C.ITEM_ROLES[0], C.ITEM_ROLES[0] + len(C.ITEM_ROLES)))


def test_category_keys_are_distinct_nonempty_strings():
    assert len(set(C.CATEGORY_KEYS)) == len(C.CATEGORY_KEYS)
    assert all(isinstance(k, str) and k for k in C.CATEGORY_KEYS)


def test_dialog_sizes_are_positive_pairs():
    for size in (C.MERGE_DECORATIONS_DIALOG_SIZE, C.INSTANCE_EDIT_DIALOG_SIZE):
        w, h = size
        assert w > 0 and h > 0


def test_vector_range_is_ordered():
    assert C.VECTOR_MIN < C.VECTOR_MAX
    assert C.VECTOR_DECIMALS >= 0


def test_format_vector_component_uses_configured_precision():
    assert C.format_vector_component(1.23456) == "1.235"
    assert C.format_vector_component(-0.0) == "-0.000" or C.format_vector_component(-0.0) == "0.000"
